'use client';

import { ArrowLeft, CalendarDays, FileText, Mail, MapPin, Phone, UserRound } from 'lucide-react';
import Link from 'next/link';
import { format } from 'date-fns';
import { useParams } from 'next/navigation';
import { useState } from 'react';
import { useAttendance, useEmployee, useEmployeeSalarySlips } from '@/lib/queries';
import { AttendanceList } from '@/components/attendance-calendar';
import { Avatar, Card, EmptyState, ErrorState, LinkButton, LoadingSkeleton, StatusBadge } from '@/components/ui';
import { formatMoney } from '@/lib/api';

const tabs = ['Overview', 'Attendance', 'Salary slips', 'Documents'] as const;
export default function EmployeeDetailPage() { const { id } = useParams<{ id: string }>(); const employee = useEmployee(id); const attendance = useAttendance(new URLSearchParams(`employeeId=${id}&limit=8`), Boolean(id)); const slips = useEmployeeSalarySlips(id); const [tab, setTab] = useState<(typeof tabs)[number]>('Overview'); if (employee.isLoading) return <LoadingSkeleton rows={8} />; if (employee.isError || !employee.data) return <ErrorState message={employee.error?.message ?? 'Employee not found'} retry={() => employee.refetch()} />; const person = employee.data; return <div><Link href="/dashboard" className="mb-5 inline-flex items-center gap-2 text-xs font-bold text-[#777982] hover:text-[#ff725c]"><ArrowLeft className="h-4 w-4" />Back to workspace</Link><Card className="mb-5 overflow-hidden"><div className="relative h-28 bg-[#1f2229]"><div className="absolute -bottom-8 left-5 sm:left-7"><Avatar name={`${person.firstName} ${person.lastName}`} src={person.avatarUrl} size="lg" /></div><div className="absolute right-5 top-5"><StatusBadge status={person.employmentStatus} /></div></div><div className="flex flex-col gap-4 px-5 pb-6 pt-12 sm:flex-row sm:items-end sm:justify-between sm:px-7"><div><h1 className="font-display text-3xl">{person.firstName} {person.lastName}</h1><p className="mt-1 text-sm text-[#777982]">{person.designation} · {person.department}</p><p className="mt-2 text-xs font-bold uppercase tracking-[0.13em] text-[#a0a1a6]">{person.employeeCode}</p></div><LinkButton href={`/employees/${id}/salary-slip`}><FileText className="h-4 w-4" />View salary slips</LinkButton></div></Card><div className="mb-6 flex gap-1 overflow-x-auto border-b border-[#e8e4dc]">{tabs.map((item) => <button key={item} className={`min-h-11 shrink-0 border-b-2 px-4 text-sm font-bold transition ${tab === item ? 'border-[#ff725c] text-[#1f2229]' : 'border-transparent text-[#92939a] hover:text-[#1f2229]'}`} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === 'Overview' && <div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><div className="space-y-5"><Card className="p-5 sm:p-6"><h2 className="mb-5 font-display text-xl">About {person.firstName}</h2><div className="grid gap-5 sm:grid-cols-2"><Info icon={<Mail />} label="Work email" value={person.email} /><Info icon={<Phone />} label="Phone" value={person.phone ?? 'Not added'} /><Info icon={<MapPin />} label="Location" value={person.location ?? 'Not added'} /><Info icon={<CalendarDays />} label="Joined" value={format(new Date(person.joiningDate), 'd MMM yyyy')} /></div></Card><Card className="p-5 sm:p-6"><h2 className="mb-5 font-display text-xl">Emergency contact</h2><div className="grid gap-5 sm:grid-cols-2"><Info icon={<UserRound />} label="Contact name" value={person.emergencyContactName ?? 'Not added'} /><Info icon={<Phone />} label="Contact phone" value={person.emergencyContactPhone ?? 'Not added'} /></div></Card></div><Card className="h-fit p-5 sm:p-6"><h2 className="mb-5 font-display text-xl">Job information</h2><div className="space-y-4"><Info icon={<UserRound />} label="Designation" value={person.designation} /><Info icon={<CalendarDays />} label="Employment type" value={person.employmentType.replace('_', ' ')} /><Info icon={<UserRound />} label="Manager" value={person.managerName ?? 'Not assigned'} /><div className="rounded-xl bg-[#eff9c7] p-4"><p className="text-xs text-[#657200]">Annual base salary</p><p className="mt-1 text-xl font-bold text-[#4d5d00]">{formatMoney(person.baseSalary)}</p></div></div></Card></div>}{tab === 'Attendance' && <Card className="p-5 sm:p-6"><div className="mb-5"><h2 className="font-display text-xl">Recent attendance</h2><p className="mt-1 text-xs text-[#85878d]">The latest time records for {person.firstName}.</p></div>{attendance.isLoading ? <LoadingSkeleton rows={6} /> : <AttendanceList records={attendance.data?.items ?? []} />}</Card>}{tab === 'Salary slips' && <Card className="p-5 sm:p-6"><div className="mb-5"><h2 className="font-display text-xl">Salary history</h2><p className="mt-1 text-xs text-[#85878d]">Payslips generated for {person.firstName}.</p></div>{slips.isLoading ? <LoadingSkeleton rows={4} /> : slips.data?.length ? <div className="space-y-2">{slips.data.map((slip) => <Link key={slip.id} href={`/employees/${id}/salary-slip?slip=${slip.id}`} className="flex items-center justify-between rounded-xl border border-[#eeeae4] px-4 py-4 transition hover:border-[#ffb1a5] hover:bg-[#fffaf1]"><div><p className="text-sm font-bold">{format(new Date(slip.year, slip.month - 1, 1), 'MMMM yyyy')}</p><p className="text-xs text-[#85878d]">Net pay · {formatMoney(slip.netSalary)}</p></div><StatusBadge status={slip.paymentStatus} /></Link>)}</div> : <EmptyState title="No salary slips yet" />}</Card>}{tab === 'Documents' && <EmptyState title="No documents yet" description="HR can add offer letters, reviews, and other people documents here." />}</div>; }
function Info({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="flex gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#f3f1ec] text-[#777982]">{icon && <span className="[&>svg]:h-4 [&>svg]:w-4">{icon}</span>}</span><div className="min-w-0"><p className="text-[11px] font-bold uppercase tracking-[0.11em] text-[#999ba1]">{label}</p><p className="mt-0.5 overflow-wrap-anywhere text-sm font-semibold">{value}</p></div></div>; }
